function mySqrt(x) {
  function goodEnough(guess) {
    return Math.abs(guess * guess - x) < 0.001;
  }
  function improve(guess) {
    return (guess + x / guess) / 2;
  }
  function sqrtIter(guess) {
    return goodEnough(guess) ? guess : sqrtIter(improve(guess));
  }
  return sqrtIter(1);
}

